def donner_indicatifs_et_canaux(apps, schema_editor):
    """Chaque équipe reçoit un indicatif (unique dans son environnement) et ses deux canaux
    d'équipe par défaut AC-<INDICATIF> (core/radio_equipe.py). Les canaux d'équipe déjà
    existants gardent leur nom (les membres les ont configurés à la main) et leur emplacement
    sur les passerelles."""
    import secrets
    import unicodedata

    from core.routage_canaux import ADRESSES_CELLULE, proposer_indicatif

    Team = apps.get_model("core", "Team")
    CanalMeshCore = apps.get_model("core", "CanalMeshCore")
    CanalMeshtastic = apps.get_model("core", "CanalMeshtastic")

    CanalMeshCore.objects.filter(equipe__isnull=False).update(sur_passerelle=True, personnalise=True)
    CanalMeshtastic.objects.filter(equipe__isnull=False).update(personnalise=True)

    pris = {}
    for env, ind in Team.objects.exclude(indicatif="").values_list("environment", "indicatif"):
        pris.setdefault(env, set()).add(ind.upper())
    for equipe in Team.objects.filter(indicatif="").order_by("created_at"):
        deja = pris.setdefault(equipe.environment, set())
        equipe.indicatif = proposer_indicatif(equipe.name, deja | ADRESSES_CELLULE)
        deja.add(equipe.indicatif)
        Team.objects.filter(pk=equipe.pk).update(indicatif=equipe.indicatif)

    def nom(equipe):
        brut = unicodedata.normalize("NFKD", "AC-" + equipe.indicatif).encode("ascii", "ignore").decode()
        return "".join(c for c in brut if c.isalnum() or c in "-_")[:11]

    avec_mt = set(CanalMeshtastic.objects.filter(equipe__isnull=False).values_list("equipe_id", flat=True))
    avec_mc = set(CanalMeshCore.objects.filter(equipe__isnull=False).values_list("equipe_id", flat=True))
    for equipe in Team.objects.all():
        commun = dict(equipe_id=equipe.pk, institution_id=equipe.institution_id, nom=nom(equipe),
                      actif=equipe.actif, environment=equipe.environment)
        if equipe.pk not in avec_mt:
            CanalMeshtastic.objects.create(psk_hex=secrets.token_hex(16), **commun)
        if equipe.pk not in avec_mc:
            CanalMeshCore.objects.create(cle_partagee_hex=secrets.token_hex(16), **commun)


